mapper.select:
select

from sys_merchant_notice n

    n.is_delete = 0

        and n.notice_title like concat('%', #{noticeTitle}, '%')

    and n.notice_type = #{noticeType}
    and n.target_scope = #{targetScope}
    and n.status = #{status}

order by n.create_time desc, n.merchant_notice_id desc

mapper.update:
update sys_merchant_notice
notice_title = #{noticeTitle}, notice_type = #{noticeType}, notice_content = #{noticeContent}, target_scope = #{targetScope}, status = #{status}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark}
where merchant_notice_id = #{merchantNoticeId} and is_delete = 0
